const input = $input.first().json.body || $input.first().json;
const { resumeText, jdText, history, analysis, authenticitySignals, lastAssessmentNote, pendingQuestions, planItem, targetQuestion } = input;
const truncate = (t, max) => !t ? '' : t.length > max ? t.slice(0, max) + '...[truncated]' : t;

// ── Interview progress ──────────────────────────────────────────
const questionsAsked = Array.isArray(history) ? history.filter(h => h.type !== 'follow_up').length : 0;
const totalPlan = 10;
const questionNumber = questionsAsked + 1;
const isFirstQuestion = questionsAsked === 0;
const isLastQuestion = questionsAsked >= totalPlan - 1;
const progressText = isFirstQuestion
  ? 'This is the OPENING of the interview — question 1 of 10.'
  : isLastQuestion
  ? `This is question ${questionNumber} of ${totalPlan} — the FINAL question. Wrap up warmly after asking it.`
  : `This is question ${questionNumber} of ${totalPlan}.`;

// ── Conversation history (last 3 Q&A pairs for context) ────────
const recentHistory = (history || []).slice(-3);
const historyText = recentHistory.length > 0
  ? recentHistory.map(h => `Q: ${h.question}\nA: ${h.answer || '(no response)'}`)
      .join('\n\n')
  : 'None — this is the first question.';

// ── Last answer context ─────────────────────────────────────────
const lastItem = history && history.length > 0 ? history[history.length - 1] : null;
const isNoteMatchingLastItem = Boolean(
  lastAssessmentNote?.question_id && lastItem?.id &&
  lastAssessmentNote.question_id === lastItem.id
);
const validNote = isNoteMatchingLastItem ? lastAssessmentNote?.note : null;

// ── Focus instruction from blueprint plan item ──────────────────
const extractedTools = analysis?.extractedTools || [];
let focusInstruction = '';
let questionTypeTarget = 'technical';

if (planItem) {
  questionTypeTarget = planItem.question_type || 'technical';

  if (planItem.category === 'gap_probe') {
    const gap = planItem.gap_ref;
    focusInstruction = `CATEGORY: gap_probe
Gap to probe: "${gap?.description || planItem.objective}"
How to approach it: "${gap?.probe_direction || 'Ask warmly how their background transfers to this area'}"
TONE: Curious and warm — frame as genuine interest, not a challenge or accusation.`;

  } else if (planItem.category === 'problem_solving') {
    focusInstruction = `CATEGORY: problem_solving
Present a real-world scenario or trade-off question.
Objective: ${planItem.objective || 'Test practical reasoning and decision-making'}
Ask "How would you approach..." or "Walk me through how you'd handle..." — not definition or memorization questions.`;

  } else if (planItem.category === 'cultural') {
    focusInstruction = `CATEGORY: cultural
Objective: ${planItem.objective || 'Understand work style, collaboration, and team fit'}
Ask about a specific real situation or preference — not a generic "tell me about yourself".
Good formats: "How do you typically..." / "Tell me about a time when..." / "What kind of environment do you..."`;

  } else {
    // technical_jd or technical_resume
    const tool = planItem.target_tool || 'the required skill';
    const mode = planItem.verification_mode || 'baseline_check';
    const matchingTool = extractedTools.find(t => t.name?.toLowerCase() === tool.toLowerCase());
    const resumeCtx = matchingTool?.resume_context || '';

    if (mode === 'verify_claim') {
      focusInstruction = `CATEGORY: ${planItem.category} — VERIFY CLAIM
Tool: "${tool}"
Candidate claims experience: "${resumeCtx || 'Listed on resume'}"
Objective: ${planItem.objective}
Ask for their OWN real experience — a specific decision they made, a problem they solved, or a trade-off they navigated using ${tool}.
AVOID: Vague openers like "Can you tell me about your experience with ${tool}?" — be specific.
EXAMPLE FRAMING: "You mentioned using ${tool} at [company] — what's a concrete example of a problem you solved with it?"`;

    } else {
      focusInstruction = `CATEGORY: ${planItem.category} — BASELINE CHECK
Tool: "${tool}"
This tool is required by the JD but does NOT appear on the resume.
Objective: ${planItem.objective}
Ask a gentle awareness question — what problem does ${tool} solve? When would they reach for it?
AVOID: Deep implementation questions. Keep it accessible — you're checking awareness, not expertise.`;
    }
  }

} else {
  // Fallback when no planItem from blueprint
  const fallbackStages = [
    { instruction: 'Ask a foundational conceptual question about the primary technology required by this role. Focus on understanding, not definition.', type: 'technical' },
    { instruction: 'Ask about a core principle or trade-off in a key technology from the JD.', type: 'technical' },
    { instruction: 'Ask about a design decision or engineering principle relevant to this role.', type: 'technical' },
    { instruction: 'Ask about a real hands-on scenario — how they implemented or debugged something with a key tool.', type: 'technical' },
    { instruction: 'Ask about a specific project from the resume — what they built, what decisions they made, what the outcome was.', type: 'technical' },
    { instruction: 'Map a resume project to a JD requirement — ask how their experience applies to what this role needs.', type: 'technical' },
    { instruction: 'Probe a potential gap or explore how their background transfers to an area the JD emphasises.', type: 'situational' },
    { instruction: 'Ask a scenario-based problem-solving question — a real-world situation they would face in this role.', type: 'situational' },
    { instruction: 'Ask about work style, collaboration, or how they handle feedback or disagreement.', type: 'cultural' },
    { instruction: 'Ask about values, adaptability, what environment they thrive in, or why this role interests them.', type: 'cultural' }
  ];
  const idx = Math.min(questionsAsked, 9);
  focusInstruction = fallbackStages[idx].instruction;
  questionTypeTarget = fallbackStages[idx].type;
}

// ── Authenticity signals ────────────────────────────────────────
const recentSignals = (authenticitySignals || []).slice(-3);
const hasRedFlags = recentSignals.some(s => s.signal === 'suspicious' || s.signal === 'inconsistent');
const authenticityContext = recentSignals.length > 0
  ? `Authenticity signals from recent answers: ${recentSignals.map(s => `${s.signal}/${s.depth}`).join(', ')}${hasRedFlags ? '\n→ Candidate has shown suspicious or inconsistent signals. You may be slightly more pointed in your next question, but stay professional and composed.' : ''}`
  : '';

// ── Required question override ──────────────────────────────────
const targetQuestionContext = targetQuestion
  ? `\nREQUIRED NEXT QUESTION: "${targetQuestion}"\nYou MUST ask this specific question next. Do not significantly rephrase it. Prefix it with a brief natural acknowledgment.`
  : '';

const pendingContext = (pendingQuestions || []).length > 0
  ? `\nQueued questions (use these if no plan item is given):\n${pendingQuestions.map((q, i) => `  ${i + 1}. ${q}`).join('\n')}`
  : '';

// ── Acknowledgment instruction based on turn context ───────────
let ackInstruction = '';
if (isFirstQuestion) {
  ackInstruction = `This is the OPENING turn. Welcome the candidate warmly in 1-2 sentences, then ask the first question. Do not acknowledge a previous answer — there isn't one. Example: "Hi, thanks for joining today. I'm Alex — I'll be leading this screening call. Let's get started."`;
} else if (lastItem?.type === 'follow_up') {
  ackInstruction = `The previous turn was a follow-up question. Acknowledge that answer in ONE brief sentence ("Got it", "Understood", "Makes sense"), then move to the next main question. Do NOT ask another follow-up.`;
} else {
  ackInstruction = `Acknowledge the most recent answer in ONE natural sentence. Do NOT repeat or summarise what they said back to them. Do NOT say "Great answer!" or "That's wonderful!" — that is sycophantic and fake. Use something like: "Got it", "That makes sense", "Noted", "Interesting — let me ask you about...", or pick up on one specific word they used and use it as a bridge.`;
}

const prompt = `You are Alex — a warm, sharp, and genuinely curious senior technical recruiter with 8+ years screening engineers for technical roles. You are very good at reading between the lines of an answer.

Your interview voice and style:
- You sound like a real person on a live call — conversational, not scripted or robotic
- You ask one clear question at a time and wait for the answer
- You reference the candidate's actual context (their resume projects, their previous answers) to make questions feel relevant and personal
- You are direct but not cold. Warm but not soft. You do not waste words.
- You never use hollow affirmations ("Great!", "Wonderful!", "Excellent answer!") — they are fake and candidates notice
- Natural fillers you DO use: "Got it", "That makes sense", "Interesting", "Right" — brief, human, real
- You keep momentum — brief acknowledge → sharp question → done

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CANDIDATE CONTEXT
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Resume:
"""
${truncate(resumeText, 2000)}
"""

Job Description:
"""
${truncate(jdText, 1200)}
"""

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
INTERVIEW STATE
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
${progressText}

Recent conversation (last 3 turns):
${historyText}

${validNote ? `Recruiter note on last answer (internal — do NOT read out): "${validNote}"` : ''}
${authenticityContext}
${targetQuestionContext}
${pendingContext}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
THIS TURN
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Focus for this question:
${focusInstruction}

STEP 1 — ACKNOWLEDGMENT:
${ackInstruction}

STEP 2 — QUESTION:
${targetQuestion
  ? 'Use the REQUIRED NEXT QUESTION above. Prefix it with your acknowledgment from Step 1.'
  : 'Craft the question based on the Focus above. Make it specific — reference the actual tool name, a real project from the resume, or a concrete scenario. One question only.'}

${isLastQuestion ? '\nCLOSING: After asking this final question, add 1 warm sentence letting the candidate know this is the last question and they are doing well.' : ''}

RULES:
- One question per turn — never stack two questions
- Stay in character as Alex throughout
- The question_text field should be ONLY the question, extracted from your full utterance

Return ONLY this JSON:
{
  "interviewer_text": "Your full spoken utterance — acknowledgment + question (+ closing if last turn)",
  "question_text": "The question portion only, extracted from interviewer_text",
  "turn_type": "question" | "follow_up" | "transition" | "closing",
  "question_type": "${questionTypeTarget}",
  "should_continue": ${isLastQuestion ? 'false' : 'true'}
}`;

return [{ json: { prompt } }];

const input = $input.first().json.body || $input.first().json;
const { originalQuestion, candidateAnswer, insufficiencyReason, gapDirection, resumeText } = input;

const gapStrategy = {
  lacks_depth: {
    instruction: 'Candidate described WHAT happened but not HOW or WHY. Ask for the underlying mechanism, a trade-off they considered, or a decision they made — not just what the outcome was.',
    good_example: 'You mentioned using Redis for caching — what specifically did you cache, and how did you decide what TTL to set?',
    bad_example: 'Can you go deeper on that?'
  },
  lacks_evidence: {
    instruction: 'Candidate made a claim with zero concrete proof. Ask for one specific anchor: a metric, a project name, a tool name, a team size, a command, or a measurable outcome.',
    good_example: 'You said you improved performance significantly — what was the before and after in terms of actual load time or request count?',
    bad_example: 'Can you give an example?'
  },
  vague: {
    instruction: 'Candidate was hedgy, generic, or buzzword-heavy. Pick one specific phrase they used and ask them to make it concrete — a specific tool, a specific decision, or a specific situation.',
    good_example: 'You mentioned "optimising the pipeline" — what was the actual bottleneck and what specifically did you change?',
    bad_example: 'Can you be more specific?'
  },
  irrelevant: {
    instruction: 'Candidate did not address the question asked. Do NOT repeat the same question. Rephrase it as a simpler, more concrete version — anchor it to something in their resume that should give them a foothold to answer.',
    good_example: 'Let me rephrase — thinking about your work at Acme, have you worked directly with PostgreSQL indexes? If so, when would you add one?',
    bad_example: 'That\'s not quite what I asked — can you answer the original question?'
  }
};

const strategy = gapStrategy[insufficiencyReason] || {
  instruction: 'Ask for one specific, concrete example that supports the claim they made.',
  good_example: 'Can you walk me through a specific instance where you did that?',
  bad_example: 'Can you elaborate?'
};

const prompt = `You are Alex, a warm but sharp senior technical recruiter conducting a live screening call. The candidate just gave an answer that was technically insufficient. Your job is to ask ONE precise follow-up question that targets the specific gap — without being confrontational or repeating yourself.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
CONTEXT
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Original question you asked:
"${originalQuestion}"

Candidate's answer:
"${candidateAnswer}"

Resume excerpt (for grounding context):
${resumeText?.slice(0, 600) || 'Not available'}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
GAP ANALYSIS
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Failure mode: ${insufficiencyReason}
Specific gap to target: ${gapDirection}
Strategy: ${strategy.instruction}

✅ EXAMPLE of a good follow-up for this failure mode:
"${strategy.good_example}"

❌ EXAMPLE of a bad follow-up to avoid:
"${strategy.bad_example}"

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
RULES FOR YOUR FOLLOW-UP QUESTION
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
1. BRIDGE: Pick up ONE specific word, phrase, or claim from the candidate's answer and use it as your opening anchor. Do not start cold.
   Example: If they said "we used microservices" → start with "You mentioned microservices — ..."

2. TARGET THE GAP: The question must directly address "${gapDirection}" — not the original question in general.

3. DO NOT REPEAT: Do not rephrase the original question. Do not ask the same thing again with different words. You are going deeper, not restarting.

4. ONE QUESTION ONLY: No compound questions. No "and also..." or "or alternatively...". One clear, focused question.

5. TONE: Curious and conversational. Sound like you genuinely want to understand, not like you caught them out.

6. AVOID these lazy openers:
   - "Can you tell me more about..."
   - "Could you elaborate on..."
   - "Can you provide more details about..."
   - "Can you give me an example of..."
   These are filler — ask the specific thing directly.

Return ONLY this JSON:
{
  "question_text": "Your follow-up question — just the question itself, no preamble",
  "question_type": "technical"
}`;

return [{ json: { prompt } }];

